/**
 * Whether retrying the same command could succeed.
 */
export function validateCommandErrorRetryable(value: unknown, path: string, out: SchemaViolation[]): void {
  checkBoolean(value, path, out);
}

/**
 * Epoch that is actually current, returned with CONTROL_EPOCH_STALE so the caller can
 * refresh rather than guess (docs/MCP_SPEC.md section 5).
 */
export function validateCommandErrorCurrentEpoch(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 0, maximum: 2147483647 });
}

/**
 * A refused or failed operation, reported with a stable code (docs/MCP_SPEC.md section
 * 12).
 */
export function validateCommandError(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["code", "message", "retryable", "current_epoch"], ["code", "message", "retryable"]);
  if (source === null) return;
  if (source["code"] !== undefined) {
    validateErrorClass(source["code"], `${path}.code`, out);
  }
  if (source["message"] !== undefined) {
    validateReasonText(source["message"], `${path}.message`, out);
  }
  if (source["retryable"] !== undefined) {
    validateCommandErrorRetryable(source["retryable"], `${path}.retryable`, out);
  }
  if (source["current_epoch"] !== undefined) {
    validateCommandErrorCurrentEpoch(source["current_epoch"], `${path}.current_epoch`, out);
  }
}

/**
 * Status of the main document response.
 */
export function validateNavigationResultHttpStatus(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 100, maximum: 599 });
}

/**
 * Whether the browser settled on a different URL than requested.
 */
export function validateNavigationResultRedirected(value: unknown, path: string, out: SchemaViolation[]): void {
  checkBoolean(value, path, out);
}

/**
 * Outcome of a navigation. Every field is page-derived and therefore untrusted.
 */
export function validateNavigationResult(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["url", "http_status", "redirected", "title"], ["url", "redirected", "title"]);
  if (source === null) return;
  if (source["url"] !== undefined) {
    validateResolvedUrl(source["url"], `${path}.url`, out);
  }
  if (source["http_status"] !== undefined) {
    validateNavigationResultHttpStatus(source["http_status"], `${path}.http_status`, out);
  }
  if (source["redirected"] !== undefined) {
    validateNavigationResultRedirected(source["redirected"], `${path}.redirected`, out);
  }
  if (source["title"] !== undefined) {
    validatePageText(source["title"], `${path}.title`, out);
  }
}

/**
 * Box of a snapshot element in CSS pixels, relative to the top-left of the document rather
 * than of the viewport, so that it can be compared with an annotation's geometry without
 * also knowing where the page happened to be scrolled to. Page-derived: it is a
 * measurement of a layout the page controls, and it is stored as a hint about where an
 * element was rather than as an assertion about where it is (docs/DOMAIN_MODEL.md section
 * 17).
 */
export function validateElementBox(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["x", "y", "width", "height"], ["x", "y", "width", "height"]);
  if (source === null) return;
  if (source["x"] !== undefined) {
    validateElementCssPixelOffset(source["x"], `${path}.x`, out);
  }
  if (source["y"] !== undefined) {
    validateElementCssPixelOffset(source["y"], `${path}.y`, out);
  }
  if (source["width"] !== undefined) {
    validateElementCssPixelOffset(source["width"], `${path}.width`, out);
  }
  if (source["height"] !== undefined) {
    validateElementCssPixelOffset(source["height"], `${path}.height`, out);
  }
}

/**
 * How the selector was chosen, strongest first. A test identifier survives a redesign; a
 * CSS path built from tag names and positions frequently does not, and naming the strategy
 * is what lets a reader weigh the selector rather than trust it.
 */
export function validateElementDescriptorSelectorStrategy(value: unknown, path: string, out: SchemaViolation[]): void {
  checkString(value, path, out, { values: ["testid","role","text","css","xpath"] });
}

/**
 * One element of a snapshot, addressable by reference until the snapshot is superseded.
 * Everything on it but the reference is page-derived and untrusted (ADR-0010): it
 * describes what the page said about itself and is never an instruction.
 */
export function validateElementDescriptor(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["ref", "role", "name", "box", "selector", "selector_strategy", "text_excerpt", "dom_fingerprint"], ["ref", "role"]);
  if (source === null) return;
  if (source["ref"] !== undefined) {
    validateElementReference(source["ref"], `${path}.ref`, out);
  }
  if (source["role"] !== undefined) {
    validateAccessibleRole(source["role"], `${path}.role`, out);
  }
  if (source["name"] !== undefined) {
    validatePageText(source["name"], `${path}.name`, out);
  }
  if (source["box"] !== undefined) {
    validateElementBox(source["box"], `${path}.box`, out);
  }
  if (source["selector"] !== undefined) {
    validateElementSelector(source["selector"], `${path}.selector`, out);
  }
  if (source["selector_strategy"] !== undefined) {
    validateElementDescriptorSelectorStrategy(source["selector_strategy"], `${path}.selector_strategy`, out);
  }
  if (source["text_excerpt"] !== undefined) {
    validatePageText(source["text_excerpt"], `${path}.text_excerpt`, out);
  }
  if (source["dom_fingerprint"] !== undefined) {
    validateSha256Hex(source["dom_fingerprint"], `${path}.dom_fingerprint`, out);
  }
}

/**
 * Number of elements described.
 */
export function validateSnapshotResultNodeCount(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 0, maximum: 500 });
}

/**
 * Whether the page had more content than the bounds allowed. A truncated snapshot is a
 * summary, never a whole-page dump.
 */
export function validateSnapshotResultTruncated(value: unknown, path: string, out: SchemaViolation[]): void {
  checkBoolean(value, path, out);
}

/**
 * Machine-readable form of the same elements.
 */
export function validateSnapshotResultElements(value: unknown, path: string, out: SchemaViolation[]): void {
  if (!checkArray(value, path, out, { minItems: 0, maxItems: 500, uniqueItems: false })) return;
  for (let index = 0; index < value.length; index += 1) {
    validateElementDescriptor(value[index], `${path}[${index}]`, out);
  }
}

/**
 * A bounded accessibility snapshot (docs/MCP_SPEC.md sections 7.4 and 13). Page-derived
 * throughout.
 */
export function validateSnapshotResult(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["snapshot_id", "viewport", "node_count", "truncated", "text", "elements"], ["snapshot_id", "viewport", "node_count", "truncated", "text", "elements"]);
  if (source === null) return;
  if (source["snapshot_id"] !== undefined) {
    validateIdentifier(source["snapshot_id"], `${path}.snapshot_id`, out);
  }
  if (source["viewport"] !== undefined) {
    validateViewport(source["viewport"], `${path}.viewport`, out);
  }
  if (source["node_count"] !== undefined) {
    validateSnapshotResultNodeCount(source["node_count"], `${path}.node_count`, out);
  }
  if (source["truncated"] !== undefined) {
    validateSnapshotResultTruncated(source["truncated"], `${path}.truncated`, out);
  }
  if (source["text"] !== undefined) {
    validateSnapshotText(source["text"], `${path}.text`, out);
  }
  if (source["elements"] !== undefined) {
    validateSnapshotResultElements(source["elements"], `${path}.elements`, out);
  }
}

/**
 * Byte length the control plane verified.
 */
export function validateScreenshotResultSizeBytes(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 1, maximum: 20971520 });
}

/**
 * Whether the capture extends beyond the viewport.
 */
export function validateScreenshotResultFullPage(value: unknown, path: string, out: SchemaViolation[]): void {
  checkBoolean(value, path, out);
}

/**
 * A screenshot that the control plane has verified and made available (docs/API.md section
 * 15, ADR-0012).
 */
export function validateScreenshotResult(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["artefact_id", "sha256", "size_bytes", "content_type", "viewport", "full_page", "captured_at"], ["artefact_id", "sha256", "size_bytes", "content_type", "viewport", "full_page", "captured_at"]);
  if (source === null) return;
  if (source["artefact_id"] !== undefined) {
    validateIdentifier(source["artefact_id"], `${path}.artefact_id`, out);
  }
  if (source["sha256"] !== undefined) {
    validateSha256Hex(source["sha256"], `${path}.sha256`, out);
  }
  if (source["size_bytes"] !== undefined) {
    validateScreenshotResultSizeBytes(source["size_bytes"], `${path}.size_bytes`, out);
  }
  if (source["content_type"] !== undefined) {
    validateImageContentType(source["content_type"], `${path}.content_type`, out);
  }
  if (source["viewport"] !== undefined) {
    validateViewport(source["viewport"], `${path}.viewport`, out);
  }
  if (source["full_page"] !== undefined) {
    validateScreenshotResultFullPage(source["full_page"], `${path}.full_page`, out);
  }
  if (source["captured_at"] !== undefined) {
    validateTimestamp(source["captured_at"], `${path}.captured_at`, out);
  }
}

/**
 * Whether the command succeeded.
 */
export function validateBrowserCommandResultOk(value: unknown, path: string, out: SchemaViolation[]): void {
  checkBoolean(value, path, out);
}

/**
 * Sequence number of the command this result answers.
 */
export function validateBrowserCommandResultSequence(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 0, maximum: 4294967295 });
}

/**
 * Epoch current at the worker when the command ran.
 */
export function validateBrowserCommandResultControlEpoch(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 0, maximum: 2147483647 });
}

/**
 * How long the command took.
 */
export function validateBrowserCommandResultDurationMs(value: unknown, path: string, out: SchemaViolation[]): void {
  checkInteger(value, path, out, { minimum: 0, maximum: 600000 });
}

/**
 * Result of one browser command. The trust rules below are enforced by the generated
 * validators on both sides, so page-derived content cannot be returned without its
 * untrusted label (ADR-0010).
 */
export function validateBrowserCommandResult(value: unknown, path: string, out: SchemaViolation[]): void {
  const source = checkObject(value, path, out, ["ok", "command", "sequence", "control_epoch", "duration_ms", "trust", "instruction_policy", "error", "navigation", "snapshot", "screenshot", "viewport"], ["ok", "command", "sequence", "control_epoch", "duration_ms", "trust", "instruction_policy"]);
  if (source === null) return;
  if (source["ok"] !== undefined) {
    validateBrowserCommandResultOk(source["ok"], `${path}.ok`, out);
  }
  if (source["command"] !== undefined) {
    validateCommandName(source["command"], `${path}.command`, out);
  }
  if (source["sequence"] !== undefined) {
    validateBrowserCommandResultSequence(source["sequence"], `${path}.sequence`, out);
  }
  if (source["control_epoch"] !== undefined) {
    validateBrowserCommandResultControlEpoch(source["control_epoch"], `${path}.control_epoch`, out);
  }
  if (source["duration_ms"] !== undefined) {
    validateBrowserCommandResultDurationMs(source["duration_ms"], `${path}.duration_ms`, out);
  }
  if (source["trust"] !== undefined) {
    validateTrustLabel(source["trust"], `${path}.trust`, out);
  }
  if (source["instruction_policy"] !== undefined) {
    validateInstructionPolicy(source["instruction_policy"], `${path}.instruction_policy`, out);
  }
  if (source["error"] !== undefined) {
    validateCommandError(source["error"], `${path}.error`, out);
  }
  if (source["navigation"] !== undefined) {
    validateNavigationResult(source["navigation"], `${path}.navigation`, out);
  }
  if (source["snapshot"] !== undefined) {
    validateSnapshotResult(source["snapshot"], `${path}.snapshot`, out);
  }
  if (source["screenshot"] !== undefined) {
    validateScreenshotResult(source["screenshot"], `${path}.screenshot`, out);
  }
  if (source["viewport"] !== undefined) {
    validateViewport(source["viewport"], `${path}.viewport`, out);
  }
  if (matchesCondition(source["trust"], ["trusted_control_plane"])) {
    forbidProperty(source, path, "navigation", "page-derived content must be labelled untrusted_browser_content (ADR-0010, docs/SECURITY.md section 11)", out);
    forbidProperty(source, path, "snapshot", "page-derived content must be labelled untrusted_browser_content (ADR-0010, docs/SECURITY.md section 11)", out);
    forbidProperty(source, path, "screenshot", "page-derived content must be labelled untrusted_browser_content (ADR-0010, docs/SECURITY.md section 11)", out);
  }
}
